import json
import logging
import re
import threading
import time

import httpx

log = logging.getLogger("llm")


class LLMError(Exception):
    pass


def extract_json(text: str) -> dict:
    if not text:
        raise LLMError("пустой ответ")
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.I | re.M)
    try:
        value = json.loads(cleaned)
        if isinstance(value, dict):
            return value
    except json.JSONDecodeError:
        pass
    start = cleaned.find("{")
    depth = 0
    in_str = False
    esc = False
    for i in range(start if start >= 0 else len(cleaned), len(cleaned)):
        ch = cleaned[i]
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
            continue
        if ch == '"':
            in_str = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                try:
                    value = json.loads(cleaned[start:i + 1])
                except json.JSONDecodeError as exc:
                    raise LLMError(f"некорректный JSON: {exc}") from exc
                if isinstance(value, dict):
                    return value
                break
    raise LLMError("в ответе нет JSON-объекта")


class LLMClient:
    def __init__(self, base_url: str, model: str, api_key: str = "", timeout: float = 120.0,
                 min_gap: float = 4.0, retries: int = 3, temperature: float | None = 0.2,
                 enabled: bool = True, on_call=None):
        self.url = base_url.rstrip("/") + "/chat/completions"
        self.model = model
        self.api_key = api_key
        self.timeout = timeout
        self.min_gap = min_gap
        self.retries = retries
        self.temperature = temperature
        self.enabled = enabled
        self.on_call = on_call
        self._lock = threading.Lock()
        self._last_call = 0.0
        self._client = httpx.Client(timeout=timeout)

    def chat(self, messages: list[dict], max_tokens: int | None = None) -> str:
        if not self.enabled:
            raise LLMError("LLM отключена настройкой LLM_ENABLED=0")
        body: dict = {"model": self.model, "messages": messages}
        if self.temperature is not None:
            body["temperature"] = self.temperature
        if max_tokens:
            body["max_tokens"] = max_tokens
        headers = {"Content-Type": "application/json"}
        if self.api_key:
            headers["Authorization"] = f"Bearer {self.api_key}"
        last_err: Exception | None = None
        with self._lock:
            for attempt in range(self.retries):
                gap = self._last_call + self.min_gap - time.monotonic()
                if gap > 0:
                    time.sleep(gap)
                started = time.monotonic()
                try:
                    resp = self._client.post(self.url, json=body, headers=headers)
                    self._last_call = time.monotonic()
                    if resp.status_code == 429 or resp.status_code >= 500:
                        raise LLMError(f"HTTP {resp.status_code}")
                    if resp.status_code >= 400:
                        self._report(False, time.monotonic() - started)
                        raise LLMError(f"HTTP {resp.status_code}: {resp.text[:200]}")
                    data = resp.json()
                    content = ((data.get("choices") or [{}])[0].get("message") or {}).get("content")
                    if not content or not content.strip():
                        raise LLMError("пустой content")
                    self._report(True, time.monotonic() - started)
                    return content
                except (httpx.HTTPError, LLMError, ValueError) as exc:
                    self._last_call = time.monotonic()
                    last_err = exc
                    if isinstance(exc, LLMError) and str(exc).startswith("HTTP 4") and "429" not in str(exc):
                        break
                    self._report(False, time.monotonic() - started)
                    log.warning("LLM call failed (%s), attempt %d/%d", exc, attempt + 1, self.retries)
                    if attempt + 1 < self.retries:
                        time.sleep(3 * (2 ** attempt))
        raise LLMError(str(last_err) if last_err else "LLM недоступна")

    def chat_json(self, messages: list[dict], validator=None) -> dict:
        last: Exception | None = None
        for _ in range(2):
            content = self.chat(messages)
            try:
                value = extract_json(content)
                if validator:
                    value = validator(value)
                return value
            except LLMError as exc:
                last = exc
                log.warning("LLM returned unusable JSON: %s", exc)
        raise LLMError(str(last))

    def _report(self, ok: bool, latency: float) -> None:
        if self.on_call:
            try:
                self.on_call(ok, latency)
            except Exception:
                pass

