:root {
  --bg: #f5f6f8;
  --surface: #ffffff;
  --surface-2: #f0f2f5;
  --border: #e2e5ea;
  --text: #16181d;
  --muted: #5f6673;
  --accent: #2f5bea;
  --accent-ink: #ffffff;
  --good: #1f9d55;
  --mixed: #d69e12;
  --bad: #d64545;
  --none: #9aa1ad;
  --good-soft: #e3f5ea;
  --bad-soft: #fbe7e7;
  --mixed-soft: #fbf3dc;
  --shadow: 0 1px 2px rgba(16, 24, 40, .06), 0 1px 3px rgba(16, 24, 40, .08);
  --radius: 12px;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f1115;
    --surface: #171a21;
    --surface-2: #1f232c;
    --border: #2a2f3a;
    --text: #e8eaee;
    --muted: #9aa3b2;
    --accent: #6f8dff;
    --accent-ink: #0b0d12;
    --good-soft: #15301f;
    --bad-soft: #3a1b1b;
    --mixed-soft: #3a3016;
    --shadow: none;
    color-scheme: dark;
  }
}
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.55 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}
a { color: var(--accent); text-decoration: none; }
a:hover { text-decoration: underline; }
img { max-width: 100%; display: block; }
h1, h2, h3 { line-height: 1.25; margin: 0 0 .5em; }
h1 { font-size: 26px; }
h2 { font-size: 19px; }
h3 { font-size: 16px; }
.muted { color: var(--muted); }
.small { font-size: 13px; }
.wrap { max-width: 1200px; margin: 0 auto; padding: 0 16px; }

.topbar { background: var(--surface); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 10; }
.topbar .wrap { display: flex; align-items: center; gap: 20px; height: 56px; }
.brand { font-weight: 700; color: var(--text); font-size: 16px; display: flex; align-items: center; gap: 8px; }
.brand-mark { width: 26px; height: 26px; border-radius: 7px; background: var(--accent); color: var(--accent-ink);
  display: grid; place-items: center; font-size: 13px; font-weight: 800; }
.nav { display: flex; gap: 4px; margin-left: auto; }
.nav a { color: var(--muted); padding: 6px 12px; border-radius: 8px; font-weight: 500; }
.nav a.active, .nav a:hover { background: var(--surface-2); color: var(--text); text-decoration: none; }

main { padding: 24px 0 48px; }
.page-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 12px; margin-bottom: 18px; }
.page-head p { margin: 0; }

.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow); }
.pad { padding: 18px; }

.filters { display: grid; grid-template-columns: 2fr 1fr 1fr auto; gap: 10px; padding: 14px; margin-bottom: 18px; }
.filters input, .filters select, .btn {
  height: 40px; border-radius: 9px; border: 1px solid var(--border); background: var(--surface); color: var(--text);
  padding: 0 12px; font: inherit; min-width: 0; width: 100%;
}
.filters input:focus, .filters select:focus { outline: 2px solid var(--accent); outline-offset: -1px; }
.btn { background: var(--accent); color: var(--accent-ink); border-color: transparent; font-weight: 600; cursor: pointer;
  width: auto; display: inline-flex; align-items: center; justify-content: center; gap: 8px; white-space: nowrap; }
.btn:hover { filter: brightness(1.06); text-decoration: none; }
.btn[disabled] { opacity: .55; cursor: progress; }
.btn.ghost { background: transparent; color: var(--text); border-color: var(--border); }
.filter-meta { display: flex; justify-content: space-between; align-items: center; gap: 8px; margin: -6px 0 14px; flex-wrap: wrap; }

.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; }
.game-tile { display: flex; flex-direction: column; overflow: hidden; color: inherit; transition: transform .12s ease, border-color .12s; }
.game-tile:hover { text-decoration: none; transform: translateY(-2px); border-color: var(--accent); }
.cover { aspect-ratio: 3 / 4; background: var(--surface-2); position: relative; overflow: hidden; }
.cover img { width: 100%; height: 100%; object-fit: cover; }
.cover .noimg { position: absolute; inset: 0; display: grid; place-items: center; color: var(--muted); font-size: 13px; }
.tile-body { padding: 12px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
.tile-title { font-weight: 650; line-height: 1.3; }
.tile-meta { font-size: 13px; color: var(--muted); }
.scores { display: flex; gap: 8px; align-items: center; margin-top: auto; }

.score { display: inline-flex; align-items: center; justify-content: center; min-width: 40px; height: 40px; padding: 0 6px;
  border-radius: 9px; font-weight: 800; font-size: 17px; color: #fff; background: var(--none); }
.score.user { border-radius: 50%; min-width: 40px; width: 40px; font-size: 15px; }
.score.good { background: var(--good); }
.score.mixed { background: var(--mixed); color: #1d1600; }
.score.bad { background: var(--bad); }
.score.lg { min-width: 64px; height: 64px; font-size: 28px; border-radius: 12px; }
.score.user.lg { width: 64px; font-size: 24px; border-radius: 50%; }
.score-label { font-size: 11px; color: var(--muted); line-height: 1.2; }
.score-box { display: flex; align-items: center; gap: 10px; }

.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip { font-size: 12px; padding: 2px 8px; border-radius: 999px; background: var(--surface-2); color: var(--muted); border: 1px solid var(--border); white-space: nowrap; }
.chip.accent { color: var(--accent); border-color: currentColor; background: transparent; }

.pager { display: flex; justify-content: center; gap: 6px; margin-top: 24px; flex-wrap: wrap; }
.pager a, .pager span { padding: 6px 12px; border-radius: 8px; border: 1px solid var(--border); background: var(--surface); color: var(--text); }
.pager .current { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }

.empty { text-align: center; padding: 48px 16px; }
.banner { padding: 10px 14px; border-radius: 10px; background: var(--mixed-soft); margin-bottom: 16px; font-size: 14px; }
.banner.ok { background: var(--good-soft); }

.hero { display: grid; grid-template-columns: 240px 1fr; gap: 24px; padding: 20px; }
.hero .cover { border-radius: 10px; }
.hero-info { display: flex; flex-direction: column; gap: 12px; min-width: 0; }
.facts { display: grid; grid-template-columns: max-content 1fr; gap: 4px 14px; font-size: 14px; margin: 0; }
.facts dt { color: var(--muted); }
.facts dd { margin: 0; }
.hero-scores { display: flex; gap: 24px; flex-wrap: wrap; }
.actions { display: flex; flex-wrap: wrap; gap: 8px; }

.section { margin-top: 20px; }
.section > h2 { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.desc { white-space: pre-line; margin: 0; }

table { width: 100%; border-collapse: collapse; font-size: 14px; }
th, td { text-align: left; padding: 9px 10px; border-bottom: 1px solid var(--border); vertical-align: top; }
th { color: var(--muted); font-weight: 600; font-size: 12px; text-transform: uppercase; letter-spacing: .03em; }
tr:last-child td { border-bottom: 0; }
.table-scroll { overflow-x: auto; }
.cell-score { display: flex; align-items: center; gap: 8px; }
.cell-score .score { min-width: 34px; height: 34px; font-size: 14px; }
.cell-score .score.user { width: 34px; min-width: 34px; }

.summary h3 { margin-top: 12px; }
.verdict { font-weight: 600; margin: 0 0 8px; }
.points { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 6px; }
.points li { padding: 7px 10px 7px 30px; border-radius: 8px; position: relative; font-size: 14px; }
.points li::before { position: absolute; left: 10px; top: 7px; font-weight: 800; }
.points.likes li { background: var(--good-soft); }
