.badge { display: inline-block; font-size: 11px; font-weight: 600; padding: 1px 7px; border-radius: 6px; background: var(--surface-2); border: 1px solid var(--border); color: var(--muted); vertical-align: middle; }
.badge.llm { color: var(--good); border-color: currentColor; background: transparent; }
.badge.warn { color: var(--mixed); border-color: currentColor; background: transparent; }
.badge.err { color: var(--bad); border-color: currentColor; background: transparent; }

details { margin-top: 12px; }
summary { cursor: pointer; color: var(--accent); font-size: 14px; }
.quotes { list-style: none; padding: 0; margin: 10px 0 0; display: flex; flex-direction: column; gap: 10px; }
.quotes li { font-size: 13px; border-left: 3px solid var(--border); padding-left: 10px; }
.quotes li.positive { border-color: var(--good); }
.quotes li.negative { border-color: var(--bad); }
.quotes li.neutral { border-color: var(--mixed); }

.video { display: grid; grid-template-columns: 320px 1fr; gap: 18px; }
.thumb { position: relative; border-radius: 10px; overflow: hidden; aspect-ratio: 16 / 9; background: #000; }
.thumb img { width: 100%; height: 100%; object-fit: cover; opacity: .92; }
.thumb .play { position: absolute; inset: 0; display: grid; place-items: center; }
.thumb .play span { width: 58px; height: 40px; border-radius: 10px; background: rgba(220, 30, 30, .92); display: grid; place-items: center; color: #fff; font-size: 18px; }
