.embed iframe { position: absolute; inset: 0; width: 100%; height: 100%; border: 0; }

.similar { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 12px; }
.similar a { color: inherit; display: flex; flex-direction: column; gap: 6px; }
