.log .WARNING { color: #f0c36b; }
.log .ERROR, .log .CRITICAL { color: #ff8a8a; }
.log .ts { color: #6f7a8f; }
.log .lg { color: #8fb3ff; }
.conn { font-size: 12px; color: var(--muted); display: inline-flex; align-items: center; gap: 6px; }

