:root {
  --bg: #f5f6f8;
  --surface: #ffffff;
  --surface-2: #f0f2f5;
  --border: #e2e5ea;
  --text: #16181d;
  --muted: #5f6673;
  --accent: #2f5bea;
  --accent-ink: #ffffff;
  --good: #1f9d55;
  --mixed: #d69e12;
  --bad: #d64545;
  --none: #9aa1ad;
  --good-soft: #e3f5ea;
  --bad-soft: #fbe7e7;
  --mixed-soft: #fbf3dc;
  --shadow: 0 1px 2px rgba(16, 24, 40, .06), 0 1px 3px rgba(16, 24, 40, .08);
  --radius: 12px;
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f1115;
    --surface: #171a21;
    --surface-2: #1f232c;
    --border: #2a2f3a;
    --text: #e8eaee;
    --muted: #9aa3b2;
    --accent: #6f8dff;
    --accent-ink: #0b0d12;
    --good-soft: #15301f;
    --bad-soft: #3a1b1b;
    --mixed-soft: #3a3016;
    --shadow: none;
    color-scheme: dark;
  }
}
* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
