cd ~/dev/skytec-metacritic/app/templates && cat > base.html <<'EOF'
<!doctype html>
<html lang="ru">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{% block title %}Игры Metacritic{% endblock %}</title>
  <link rel="stylesheet" href="/static/style.css?v=3">
  <link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='8' fill='%232f5bea'/%3E%3Ctext x='16' y='22' font-size='16' font-family='Arial' font-weight='700' fill='white' text-anchor='middle'%3EMC%3C/text%3E%3C/svg%3E">
</head>
<body>
  <header class="topbar">
    <div class="wrap">
      <a class="brand" href="/"><span class="brand-mark">MC</span><span>Игры <span class="full">Metacritic: дайджест</span></span></a>
      <nav class="nav">
        <a href="/" class="{% if request.url.path == '/' or request.url.path.startswith('/game') %}active{% endif %}">Игры</a>
        <a href="/monitor" class="{% if request.url.path == '/monitor' %}active{% endif %}">Мониторинг</a>
      </nav>
    </div>
