EOF
cat > _macros.html <<'EOF'
{% macro meta_badge(score, size='') -%}
<span class="score {{ score|meta_class }} {{ size }}" title="Metascore">{{ score if score is not none else '—' }}</span>
{%- endmacro %}
{% macro user_badge(score, size='') -%}
<span class="score user {{ score|user_class }} {{ size }}" title="Userscore">{{ score|user_fmt }}</span>
{%- endmacro %}
