{% extends "base.html" %}
{% from "_macros.html" import meta_badge, user_badge, cover %}
{% block title %}Игры Metacritic{% endblock %}
{% block content %}
<div class="page-head">
  <div>
    <h1>Новые игры с Metacritic</h1>
